<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('User/user_spread_list')}">平台推广商家佣金列表</a>					<a href="{pigcms{:U('User/user_check_list')}" class="on">平台推广商家用户审核列表</a>				</ul>			</div>			<table class="search_table" width="100%">				<tr>					<td>						<form action="{pigcms{:U('User/user_check_list')}" method="get">							<input type="hidden" name="c" value="User"/>							<input type="hidden" name="a" value="user_check_list"/>							筛选: <input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>							<select name="searchtype">								<option value="uid" <if condition="$_GET['searchtype'] eq 'uid'">selected="selected"</if>>用户ID</option>								<option value="nickname" <if condition="$_GET['searchtype'] eq 'nickname'">selected="selected"</if>>昵称</option>								<option value="phone" <if condition="$_GET['searchtype'] eq 'phone'">selected="selected"</if>>手机号</option>							</select>							<input type="submit" style="margin-right:20px;" value="查询" class="button"/>						</form>											</td>				</tr>			</table>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col/>							<col width="200" align="center"/>						</colgroup>						<thead>							<tr>								<th>ID</th>								<th>昵称</th>								<th>手机号</th>								<th class="textcenter">状态</th>								<th class="textcenter">申请时间</th>								<th class="textcenter">操作</th>							</tr>						</thead>						<tbody>							<if condition="is_array($user_list)">								<volist name="user_list" id="vo">									<tr>										<td>{pigcms{$vo.uid}</td>										<td>{pigcms{$vo.nickname}</td>										<td>{pigcms{$vo.phone}</td>										<td class="textcenter">											<if condition="$vo['can_c2b_spread'] eq 1"><font color="orange">申请中</font>												<elseif condition="$vo['can_c2b_spread'] eq 2" /><font color="green">审核通过</font>												<elseif condition="$vo['can_c2b_spread'] eq 3" /><font color="red">审核未通过</font>												<else /><font color="red">未知状态</font>											</if>										</td>                                        <td class="textcenter">{pigcms{$vo.reply_time}</td>                                        <td class="textcenter">											<if condition="$vo['can_c2b_spread'] eq 1">											<a href="javascript:void(0);" class="delete_row" parameter="uid={pigcms{$vo['uid']}" url="/admin.php?g=System&c=User&a=can_spread">通过</a>											|											<a href="javascript:void(0);" class="delete_row" parameter="uid={pigcms{$vo['uid']}&type=0" url="/admin.php?g=System&c=User&a=can_spread">拒绝</a>											</if>										</td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="6">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="6">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div>		<script>		 var url = "{pigcms{$config.site_url}"</script><include file="Public:footer"/>